   291→/// Wrapper over a `DataColumnSidecar` for which we have completed kzg verification.
   292→#[derive(Debug, Derivative, Clone, Encode, Decode)]
   293→#[derivative(PartialEq, Eq)]
   294→#[ssz(struct_behaviour = "transparent")]
   295→pub struct KzgVerifiedDataColumn<E: EthSpec> {
   296→    data: Arc<DataColumnSidecar<E>>,
   297→}
   298→
   299→impl<E: EthSpec> KzgVerifiedDataColumn<E> {
   300→    pub fn new(
   301→        data_column: Arc<DataColumnSidecar<E>>,
   302→        kzg: &Kzg,
   303→    ) -> Result<Self, (Option<ColumnIndex>, KzgError)> {
   304→        verify_kzg_for_data_column(data_column, kzg)
   305→    }
   306→
   307→    /// Mark a data column as KZG verified. Caller must ONLY use this on columns constructed
   308→    /// from EL blobs.
   309→    pub fn from_execution_verified(data_column: Arc<DataColumnSidecar<E>>) -> Self {
   310→        Self { data: data_column }
   311→    }
   312→
   313→    /// Create a `KzgVerifiedDataColumn` from `DataColumnSidecar` for testing ONLY.
   314→    pub(crate) fn __new_for_testing(data_column: Arc<DataColumnSidecar<E>>) -> Self {
   315→        Self { data: data_column }
   316→    }
   317→
   318→    pub fn from_batch_with_scoring(
   319→        data_columns: Vec<Arc<DataColumnSidecar<E>>>,
   320→        kzg: &Kzg,
   321→    ) -> Result<Vec<Self>, (Option<ColumnIndex>, KzgError)> {
   322→        verify_kzg_for_data_column_list(data_columns.iter(), kzg)?;
   323→        Ok(data_columns
   324→            .into_iter()
   325→            .map(|column| Self { data: column })
   326→            .collect())
   327→    }
   328→
   329→    pub fn to_data_column(self) -> Arc<DataColumnSidecar<E>> {
   330→        self.data
   331→    }
   332→    pub fn as_data_column(&self) -> &DataColumnSidecar<E> {
   333→        &self.data
   334→    }
   335→    /// This is cheap as we're calling clone on an Arc
   336→    pub fn clone_data_column(&self) -> Arc<DataColumnSidecar<E>> {
   337→        self.data.clone()
   338→    }
   339→
   340→    pub fn index(&self) -> ColumnIndex {
   341→        self.data.index
   342→    }
   343→}
