   345→pub type CustodyDataColumnList<E> =
   346→    VariableList<CustodyDataColumn<E>, <E as EthSpec>::NumberOfColumns>;
   347→
   348→/// Data column that we must custody
   349→#[derive(Debug, Derivative, Clone, Encode, Decode)]
   350→#[derivative(PartialEq, Eq, Hash(bound = "E: EthSpec"))]
   351→#[ssz(struct_behaviour = "transparent")]
   352→pub struct CustodyDataColumn<E: EthSpec> {
   353→    data: Arc<DataColumnSidecar<E>>,
   354→}
   355→
   356→impl<E: EthSpec> CustodyDataColumn<E> {
   357→    /// Mark a column as custody column. Caller must ensure that our current custody requirements
   358→    /// include this column
   359→    pub fn from_asserted_custody(data: Arc<DataColumnSidecar<E>>) -> Self {
   360→        Self { data }
   361→    }
   362→
   363→    pub fn into_inner(self) -> Arc<DataColumnSidecar<E>> {
   364→        self.data
   365→    }
   366→    pub fn as_data_column(&self) -> &Arc<DataColumnSidecar<E>> {
   367→        &self.data
   368→    }
   369→    /// This is cheap as we're calling clone on an Arc
   370→    pub fn clone_arc(&self) -> Arc<DataColumnSidecar<E>> {
   371→        self.data.clone()
   372→    }
   373→    pub fn index(&self) -> u64 {
   374→        self.data.index
   375→    }
   376→}
